<h2>Calculate solution dilution with C1V1 = C2V2</h2><p class="lead">Find stock volume and diluent volume for a target concentration and final volume.</p><div class="notice">Sigma-Aldrich and Thermo Fisher both use C1V1=C2V2 for dilution of solutions with known concentration. Keep concentration units consistent.</div><div class="form-grid"><div class="field"><label for="c1">Stock concentration</label><input id="c1" type="number" value="100" min="0.000000001" step="any"></div><div class="field"><label for="c2">Desired concentration</label><input id="c2" type="number" value="10" min="0" step="any"></div><div class="field"><label for="v2">Desired final volume (mL)</label><input id="v2" type="number" value="50" min="0.000001" step="any"></div></div><div class="tool-actions"><button class="btn btn-primary" id="calc" type="button">Calculate</button><button class="btn btn-secondary" id="reset" type="button">Reset</button></div><div class="result-box"><div class="result-grid"><div class="metric"><span>Stock volume required</span><strong id="v1">—</strong></div><div class="metric"><span>Diluent volume</span><strong id="diluent">—</strong></div><div class="metric"><span>Dilution factor</span><strong id="factor">—</strong></div><div class="metric"><span>Stock fraction of final volume</span><strong id="fraction">—</strong></div></div><div id="note" class="helper" style="margin-top:12px"></div></div><script>
(()=>{
const $=id=>document.getElementById(id); const num=id=>Number($(id).value); const fmt=(v,d=2)=>Number.isFinite(v)?v.toLocaleString(undefined,{maximumFractionDigits:d}):'—';
const defaults={}; document.querySelectorAll('.tool-panel input,.tool-panel select,.tool-panel textarea').forEach(el=>defaults[el.id]=el.value);
function clear(){$('v1').textContent='—';$('diluent').textContent='—';$('factor').textContent='—';$('fraction').textContent='—'; const n=$('note'); if(n){n.textContent='';n.className='helper';}}
function calculate(){try{const c1=num('c1'),c2=num('c2'),v2=num('v2');if(!(c1>0&&c2>=0&&v2>0&&c2<=c1))throw 0;const v1=c2*v2/c1,di=v2-v1;$('v1').textContent=fmt(v1,6)+' mL';$('diluent').textContent=fmt(di,6)+' mL';$('factor').textContent=c2>0?fmt(c1/c2,4)+'×':'Infinite';$('fraction').textContent=fmt(v1/v2*100,4)+'%';$('note').textContent='This uses C1V1 = C2V2 and assumes concentration units are the same and volumes are additive enough for the intended laboratory preparation.';}catch(e){clear(); const n=$('note'); if(n){n.textContent='Please check the inputs and try again.';n.className='helper danger';}}}
const c=$('calc'); if(c)c.addEventListener('click',calculate); const r=$('reset'); if(r)r.addEventListener('click',()=>{Object.entries(defaults).forEach(([id,v])=>{if($(id))$(id).value=v});calculate();});
document.querySelectorAll('.tool-panel input,.tool-panel select,.tool-panel textarea').forEach(el=>el.addEventListener('input',calculate));
calculate();
})();
</script>
